package com.yeyamo_mobile.api.culture_service.infrastructure.web;
import com.yeyamo_mobile.api.culture_service.application.CultureException;import java.time.Instant;import java.util.*;import org.slf4j.MDC;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler{record ErrorResponse(Instant timestamp,int status,String code,String message,String correlationId,List<String>errors){}@ExceptionHandler(CultureException.class)ResponseEntity<ErrorResponse> culture(CultureException e){return ResponseEntity.status(e.getStatus()).body(new ErrorResponse(Instant.now(),e.getStatus().value(),e.getCode(),e.getMessage(),cid(),List.of()));}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class})ResponseEntity<ErrorResponse> invalid(RuntimeException e){return ResponseEntity.badRequest().body(new ErrorResponse(Instant.now(),400,"INVALID_STATE",e.getMessage(),cid(),List.of()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e){List<String>x=e.getBindingResult().getFieldErrors().stream().map(v->v.getField()+": "+v.getDefaultMessage()).toList();return ResponseEntity.badRequest().body(new ErrorResponse(Instant.now(),400,"VALIDATION_ERROR","Requête invalide",cid(),x));}private String cid(){return Optional.ofNullable(MDC.get("correlationId")).orElse("unknown");}}
